(async () => {
  const checks=[];
  const assert=(ok,message='assertion failed')=>{if(!ok)throw Error(message);};
  const equal=(actual,expected)=>assert(JSON.stringify(actual)===JSON.stringify(expected),JSON.stringify({actual,expected}));
  const raises=(action,C,name)=>{let error;try{action();}catch(value){error=value;}assert(error instanceof C&&(!name||error.name===name),'expected '+(name||C.name)+', got '+error);};
  for(const [index,w] of [window,document.querySelector('iframe').contentWindow].entries()) {
    const P=w.RTCPeerConnection,T=w.RTCRtpTransceiver,S=w.RTCRtpSender,R=w.RTCRtpReceiver;
    const check=async(name,action)=>{const key=index+':'+name;globalThis.__codecCurrentCheck=key;try{await action();checks.push({name:key,passed:true});}catch(error){checks.push({name:key,passed:false,error:{name:error.name,message:error.message}});}};
    const withPC=async(action)=>{const pc=new P();try{await action(pc);}finally{pc.close();}};
    await check('illegal RTP constructors',()=>{for(const C of [T,S,R]){raises(()=>new C(),w.TypeError);raises(()=>C(),w.TypeError);}});
    await check('initial fresh callee realm collections',()=>withPC(pc=>{for(const key of ['getSenders','getReceivers','getTransceivers']){const a=pc[key](),b=pc[key]();assert(a instanceof w.Array&&a!==b);equal(a,[]);}}));
    for(const kind of ['audio','video'])await check(kind+' native graph and initial state',()=>withPC(pc=>{
      const t=pc.addTransceiver(kind);assert(t instanceof T&&t.sender instanceof S&&t.receiver instanceof R);assert(t.sender.track===null&&t.sender.transport===null&&t.receiver.transport===null);assert(t.mid===null&&t.currentDirection===null&&t.direction==='sendrecv'&&t.stopped===false);
      const track=t.receiver.track;assert(track instanceof w.MediaStreamTrack&&track.kind===kind&&track.enabled&&track.muted&&track.readyState==='live'&&typeof track.id==='string'&&track.id.length>0);
      assert(pc.getTransceivers()[0]===t&&pc.getSenders()[0]===t.sender&&pc.getReceivers()[0]===t.receiver);assert(t.sender===t.sender&&track===t.receiver.track);
    }));
    await check('insertion order and collection isolation',()=>withPC(pc=>{const a=pc.addTransceiver('audio'),b=pc.addTransceiver('audio'),c=pc.addTransceiver('video');const list=pc.getTransceivers();list.splice(0,3);equal(pc.getTransceivers().map(t=>t.receiver.track.kind),['audio','audio','video']);assert(a!==b&&a.receiver.track!==b.receiver.track&&a.receiver.track.id!==b.receiver.track.id&&pc.getTransceivers()[2]===c);}));
    await check('track union uses native identity before string coercion',()=>withPC(pc=>{const track=pc.addTransceiver('video').receiver.track;Object.defineProperty(track,'kind',{get(){throw Error('author kind getter');}});track.toString=()=>{throw Error('track coercion');};const a=pc.addTransceiver(track);assert(a.sender.track===track&&a.receiver.track!==track&&a.receiver.track.kind==='video');}));
    await check('author proxy is not a native track union',()=>withPC(pc=>{const real=pc.addTransceiver('audio').receiver.track;const proxy=new Proxy(real,{get(target,key){if(key===Symbol.toPrimitive)return()=> 'not-a-media-kind';throw Error('unexpected trap');}});raises(()=>pc.addTransceiver(proxy),w.TypeError);}));
    await check('full dictionary conversion precedes invalid kind',()=>withPC(pc=>{const reads=[];raises(()=>pc.addTransceiver('invalid',{get direction(){reads.push('direction');return 'sendrecv';},get sendEncodings(){reads.push('sendEncodings');return [];},get streams(){reads.push('streams');return [];}}),w.TypeError);equal(reads,['direction','sendEncodings','streams']);assert(pc.getTransceivers().length===0);}));
    await check('conversion getter exceptions retain identity',()=>withPC(pc=>{const sentinel={};try{pc.addTransceiver('audio',{get streams(){throw sentinel;}});assert(false);}catch(error){assert(error===sentinel);}assert(pc.getTransceivers().length===0);}));
    await check('required arguments and kinds',()=>withPC(pc=>{raises(()=>pc.addTransceiver(),w.TypeError);for(const kind of [undefined,null,'Audio','VIDEO','',42,Symbol()])raises(()=>pc.addTransceiver(kind),w.TypeError);}));
    await check('streams are converted by native brand',()=>withPC(pc=>{const stream=new w.MediaStream();pc.addTransceiver('audio',{streams:[stream,stream]});for(const value of [{},Object.create(stream),new Proxy(stream,{})])raises(()=>pc.addTransceiver('audio',{streams:[value]}),w.TypeError);}));
    await check('closed state after conversion and kind validation',()=>{const pc=new P();pc.close();const reads=[];raises(()=>pc.addTransceiver('audio',{get streams(){reads.push('streams');return [];}}),w.DOMException,'InvalidStateError');equal(reads,['streams']);raises(()=>pc.addTransceiver('invalid'),w.TypeError);raises(()=>pc.addTransceiver('audio',{sendEncodings:[{rid:'!'}]}),w.DOMException,'InvalidStateError');});
    for(const direction of ['sendrecv','sendonly','recvonly','inactive'])await check('direction '+direction,()=>withPC(pc=>{const t=pc.addTransceiver('audio',{direction});assert(t.direction===direction&&t.currentDirection===null);t.direction=direction;assert(t.direction===direction);t.direction='inactive';assert(t.direction==='inactive'&&t.currentDirection===null);}));
    await check('invalid direction setter leaves state intact',()=>withPC(pc=>{const t=pc.addTransceiver('audio');for(const value of ['invalid',null,undefined]){t.direction=value;assert(t.direction==='sendrecv');}for(const value of ['stopped',Symbol()]){raises(()=>{t.direction=value;},w.TypeError);assert(t.direction==='sendrecv');}}));
    await check('encoding dictionary ancestor and member order',()=>withPC(pc=>{const reads=[],encoding={};for(const [name,value] of [['rid','a'],['active',true],['codec',undefined],['maxBitrate',64000],['maxFramerate',30],['scaleResolutionDownBy',2]])Object.defineProperty(encoding,name,{get(){reads.push(name);return value;}});pc.addTransceiver('video',{sendEncodings:[encoding]});equal(reads,['rid','active','codec','maxBitrate','maxFramerate','scaleResolutionDownBy']);}));
    for(const kind of ['audio','video']) {
      for(const [name,encodings] of [['punctuation',[{rid:'a-b'}]],['empty',[{rid:''}]],['length',[{rid:'abcdefghijklmnopq'}]],['partial',[{rid:'a'},{}]],['duplicates',[{rid:'a'},{rid:'a'}]]])await check(kind+' RID validation '+name,()=>withPC(pc=>{raises(()=>pc.addTransceiver(kind,{sendEncodings:encodings}),w.TypeError);assert(pc.getTransceivers().length===0);}));
      await check(kind+' valid encodings',()=>withPC(pc=>{pc.addTransceiver(kind,{sendEncodings:[{rid:'A1',active:false,maxBitrate:1234},{rid:'b2',scaleResolutionDownBy:2}]});assert(pc.getTransceivers().length===1);}));
    }
    await check('audio discards video-only range constraints',()=>withPC(pc=>{pc.addTransceiver('audio',{sendEncodings:[{scaleResolutionDownBy:0,maxFramerate:-2}]});}));
    await check('finite WebIDL double conversion precedes audio discard',()=>withPC(pc=>{for(const key of ['scaleResolutionDownBy','maxFramerate'])for(const value of [Infinity,-Infinity,NaN])raises(()=>pc.addTransceiver('audio',{sendEncodings:[{[key]:value}]}),w.TypeError);}));
    await check('all video encodings validated before truncation',()=>withPC(pc=>{raises(()=>pc.addTransceiver('video',{sendEncodings:[{rid:'a'},{rid:'b'},{rid:'c'},{rid:'d',scaleResolutionDownBy:.5}]}),w.RangeError);assert(pc.getTransceivers().length===0);}));
    await check('video range errors',()=>withPC(pc=>{for(const encoding of [{scaleResolutionDownBy:0},{scaleResolutionDownBy:.5},{maxFramerate:-1}])raises(()=>pc.addTransceiver('video',{sendEncodings:[encoding]}),w.RangeError);}));
    for(const kind of ['audio','video'])await check(kind+' codec preferences and reset',()=>withPC(async pc=>{
      const t=pc.addTransceiver(kind);const caps=R.getCapabilities(kind).codecs;t.setCodecPreferences(caps);t.setCodecPreferences([]);
      const codec=caps.find(c=>kind==='audio'?c.mimeType==='audio/opus':c.mimeType==='video/VP8');t.setCodecPreferences([codec,codec]);const offer=await pc.createOffer();const lines=offer.sdp.split('\r\n').filter(l=>l.startsWith('a=rtpmap:'));assert(lines.length===1&&lines[0].includes(kind==='audio'?'opus':'VP8'));assert(t.mid===null&&t.currentDirection===null);
    }));
    await check('codec dictionary inherited property conversion order',()=>withPC(pc=>{const t=pc.addTransceiver('audio'),reads=[],codec=R.getCapabilities('audio').codecs[0],arg={};for(const name of ['channels','clockRate','mimeType','sdpFmtpLine'])Object.defineProperty(arg,name,{get(){reads.push(name);return codec[name];}});t.setCodecPreferences([arg]);equal(reads,['channels','clockRate','mimeType','sdpFmtpLine']);}));
    await check('codec iterable errors retain identity and previous snapshot',()=>withPC(async pc=>{const t=pc.addTransceiver('video'),vp8=R.getCapabilities('video').codecs.find(c=>c.mimeType==='video/VP8');t.setCodecPreferences([vp8]);const sentinel={};try{t.setCodecPreferences({[Symbol.iterator](){throw sentinel;}});assert(false);}catch(error){assert(error===sentinel);}assert((await pc.createOffer()).sdp.includes('VP8'));}));
    await check('unsupported codec errors',()=>withPC(pc=>{const t=pc.addTransceiver('audio'),codec=R.getCapabilities('audio').codecs[0];for(const changed of [{mimeType:'video/VP8'},{clockRate:1},{channels:3},{sdpFmtpLine:'unknown=1'}])raises(()=>t.setCodecPreferences([{...codec,...changed}]),w.DOMException,'InvalidModificationError');for(const value of [undefined,null,{},[{mimeType:'audio/opus'}]])raises(()=>t.setCodecPreferences(value),w.TypeError);}));
    await check('auxiliary-only codec list rejected',()=>withPC(pc=>{const t=pc.addTransceiver('video');for(const name of ['video/rtx','video/red','video/ulpfec'])raises(()=>t.setCodecPreferences(R.getCapabilities('video').codecs.filter(c=>c.mimeType===name)),w.DOMException,'InvalidModificationError');}));
    await check('codec inputs snapshotted without author getters during offer',()=>withPC(async pc=>{const t=pc.addTransceiver('video'),codec=R.getCapabilities('video').codecs.find(c=>c.mimeType==='video/VP8'),array=[codec];t.setCodecPreferences(array);array.length=0;Object.defineProperty(codec,'mimeType',{get(){throw Error('late getter');}});assert((await pc.createOffer()).sdp.includes('VP8'));}));
    await check('RTP getters and methods reject forged and author proxies',()=>withPC(pc=>{
      const t=pc.addTransceiver('audio');for(const [C,real,names] of [[P,pc,['getTransceivers','getSenders','getReceivers','addTransceiver']],[T,t,['mid','sender','receiver','direction','currentDirection','stop','setCodecPreferences']],[S,t.sender,['track','transport']],[R,t.receiver,['track','transport']]]) {
        for(const name of names){const descriptor=Object.getOwnPropertyDescriptor(C.prototype,name),f=descriptor.get??descriptor.value;for(const fake of [{},Object.create(C.prototype),Object.create(real),new Proxy(real,{})])raises(()=>f.call(fake),w.TypeError);}
      }
    }));
    await check('brand rejection before conversion',()=>withPC(pc=>{const t=pc.addTransceiver('audio');let reads=0;raises(()=>T.prototype.setCodecPreferences.call(new Proxy(t,{}),{[Symbol.iterator](){reads++;return [][Symbol.iterator]();}}),w.TypeError);raises(()=>P.prototype.addTransceiver.call({},'audio',{get direction(){reads++;return 'sendrecv';}}),w.TypeError);assert(reads===0);}));
    await check('stop leaves stopping transceiver in collections',()=>withPC(async pc=>{const a=pc.addTransceiver('audio'),v=pc.addTransceiver('video');a.stop();a.stop();assert(a.direction==='stopped'&&a.currentDirection===null&&a.stopped===true);assert(pc.getTransceivers()[0]===a&&pc.getSenders()[0]===a.sender&&pc.getReceivers()[0]===a.receiver);raises(()=>{a.direction='sendonly';},w.DOMException,'InvalidStateError');a.direction='invalid';assert(a.direction==='stopped');const sdp=(await pc.createOffer()).sdp;assert(!sdp.includes('m=audio')&&sdp.includes('m=video')&&v.direction==='sendrecv');}));
    await check('receiver ended is one trusted asynchronous event',()=>withPC(async pc=>{const t=pc.addTransceiver('audio'),track=t.receiver.track;let count=0,synchronous=true;const ended=new Promise(resolve=>{track.onended=e=>{count++;assert(!synchronous&&e.isTrusted&&e.target===track&&e instanceof w.Event&&track.readyState==='ended');resolve();};});t.stop();t.stop();assert(count===0);synchronous=false;await Promise.race([ended,new Promise((_,reject)=>setTimeout(()=>reject(Error('ended task timeout')),1000))]);assert(count===1&&track.readyState==='ended');}));
    await check('author track stop suppresses queued ended event',()=>withPC(async pc=>{const t=pc.addTransceiver('audio'),track=t.receiver.track;let events=0;track.onended=()=>events++;t.stop();track.stop();const barrier=pc.addTransceiver('video');const done=new Promise(resolve=>{barrier.receiver.track.onended=resolve;});barrier.stop();await done;assert(events===0&&track.readyState==='ended');}));
    await check('close stops transceivers and rejects stop after close',()=>{const pc=new P(),t=pc.addTransceiver('audio');pc.close();pc.close();assert(t.direction==='stopped'&&t.currentDirection==='stopped');assert(pc.getTransceivers()[0]===t&&pc.getSenders().length===0&&pc.getReceivers().length===0);raises(()=>t.stop(),w.DOMException,'InvalidStateError');t.setCodecPreferences([]);});
    await check('multiple media sections use direction and unique mids',()=>withPC(async pc=>{pc.addTransceiver('video',{direction:'sendonly'});pc.addTransceiver('audio',{direction:'inactive'});pc.addTransceiver('video',{direction:'recvonly'});pc.createDataChannel('data');const sdp=(await pc.createOffer()).sdp,sections=sdp.split('m=').slice(1),mids=sections.map(s=>s.match(/a=mid:(\S+)/)[1]);assert(sections.length===4&&new Set(mids).size===4&&sdp.includes('a=group:BUNDLE '+mids.join(' ')));assert(sections[0].includes('a=sendonly')&&sections[1].includes('a=inactive')&&sections[2].includes('a=recvonly'));}));
    await check('negotiationneeded task coalesces same-turn changes',()=>withPC(async pc=>{let count=0;const event=new Promise(resolve=>{pc.onnegotiationneeded=e=>{count++;assert(e.isTrusted&&e instanceof w.Event);resolve();};});pc.addTransceiver('audio').direction='sendonly';pc.addTransceiver('video');await Promise.race([event,new Promise((_,reject)=>setTimeout(()=>reject(Error('negotiation task timeout')),1000))]);assert(count===1);}));
    await check('closed peer suppresses queued negotiation notification',async()=>{const pc=new P();let count=0;pc.onnegotiationneeded=()=>count++;pc.addTransceiver('audio');pc.close();const barrier=new P();const t=barrier.addTransceiver('audio');const done=new Promise(resolve=>{t.receiver.track.onended=resolve;});t.stop();await done;barrier.close();assert(count===0);});
  }
  globalThis.__uiEventResults={complete:true,total:checks.length,passed:checks.filter(row=>row.passed).length,checks};
  return checks.every(row=>row.passed);
})()
